package main

import (
	"fmt"
	"log"
)

func Delete(val int) (int, error) {
	if val < 0 {
		return 0, fmt.Errorf("invalid value: %d", val)
	}
	return val * 8, nil
}

func main() {
	result, err := Delete(12)
	if err != nil {
		log.Fatal(err)
	}
	fmt.Println(result)
}
